// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 mintAmount, address target) public {
        vm.assume(target != address(0));
        uint256 sumBefore = c.balanceOf(target) + c.balanceOf(address(this));
        c.mintToken(target, mintAmount);
        uint256 sumAfter = c.balanceOf(target) + c.balanceOf(address(this));
        assertEq(c.totalSupply(), sumAfter);
    }
}
